/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 * }
 */
// 合併排序：快慢指針切半 → 遞迴排序 → 合併
// 時間複雜度: O(n log n)，空間複雜度: O(log n)
function sortList(head) {
    if (!head || !head.next)
        return head;
    let slow = head, fast = head.next;
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
    }
    const right = slow.next;
    slow.next = null; // 切斷成兩半
    let a = sortList(head), b = sortList(right);
    const dummy = new ListNode(0);
    let tail = dummy;
    while (a && b) {
        if (a.val <= b.val) {
            tail.next = a;
            a = a.next;
        }
        else {
            tail.next = b;
            b = b.next;
        }
        tail = tail.next;
    }
    tail.next = a ?? b;
    return dummy.next;
}

